pub const DETAILS: &str = r##"<section class="section-light hd" data-nav="inverted" data-home-details aria-labelledby="hd-title" data-astro-cid-j3ey47lz><div class="container" data-astro-cid-j3ey47lz><div class="section-meta" data-astro-cid-j3ey47lz><span class="label-small" data-astro-cid-j3ey47lz>Détails</span><span class="label-small" data-astro-cid-j3ey47lz>Portail des licences</span><span class="label-small" data-astro-cid-j3ey47lz>Kadenz</span></div><div class="hd-head" data-reveal="title" data-astro-cid-j3ey47lz><h2 id="hd-title" class="heading-h2 hd-title" data-astro-cid-j3ey47lz>Tout est dans les détails.<br data-astro-cid-j3ey47lz><span class="muted" data-astro-cid-j3ey47lz>Les règles du portail.</span></h2></div></div><div class="hd-gallery" data-slider-root data-hd-gallery data-astro-cid-j3ey47lz><div class="hd-arrows" data-astro-cid-j3ey47lz><button type="button" class="hd-arrow" data-slider-prev aria-label="Précédent" data-astro-cid-j3ey47lz><svg viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M224,128a8,8,0,0,1-8,8H59.31l58.35,58.34a8,8,0,0,1-11.32,11.32l-72-72a8,8,0,0,1,0-11.32l72-72a8,8,0,0,1,11.32,11.32L59.31,120H216A8,8,0,0,1,224,128Z" data-astro-cid-j3ey47lz></path></svg></button><button type="button" class="hd-arrow" data-slider-next aria-label="Suivant" data-astro-cid-j3ey47lz><svg viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M221.66,133.66l-72,72a8,8,0,0,1-11.32-11.32L196.69,136H40a8,8,0,0,1,0-16H196.69L138.34,61.66a8,8,0,0,1,11.32-11.32l72,72A8,8,0,0,1,221.66,133.66Z" data-astro-cid-j3ey47lz></path></svg></button></div><div data-astro-cid-j3ey47lz><div class="slider-frame" data-slider-frame data-astro-cid-kb4uamjl><div class="slider hd-slider" data-slider data-infinite="true" data-drag="true" data-center="true" data-reveal="cards" role="region" aria-roledescription="carousel" aria-label="Les règles du portail" data-astro-cid-kb4uamjl><div class="hd-slide" data-astro-cid-j3ey47lz><article class="st-26 fc fc--picture" data-astro-cid-a5zxh5oa><div class="fc-media" data-astro-cid-a5zxh5oa><div class="hd-art hd-art--me" aria-hidden="true" data-astro-cid-j3ey47lz><canvas data-motif="P" data-cadre="vignette" data-piece="quart" data-forme="fronton" data-decalage="0" aria-hidden="true" data-astro-cid-j3ey47lz></canvas></div><button type="button" class="hd-pause" data-hd-pause aria-pressed="false" aria-label="Pause" data-astro-cid-j3ey47lz><svg class="hd-pause-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M216,48V208a16,16,0,0,1-16,16H160a16,16,0,0,1-16-16V48a16,16,0,0,1,16-16h40A16,16,0,0,1,216,48ZM96,32H56A16,16,0,0,0,40,48V208a16,16,0,0,0,16,16H96a16,16,0,0,0,16-16V48A16,16,0,0,0,96,32Z" data-astro-cid-j3ey47lz></path></svg><svg class="hd-play-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M240,128a15.74,15.74,0,0,1-7.6,13.51L88.32,229.65a16,16,0,0,1-16.2.3A15.86,15.86,0,0,1,64,216.13V39.87a15.86,15.86,0,0,1,8.12-13.82,16,16,0,0,1,16.2.3L232.4,114.49A15.74,15.74,0,0,1,240,128Z" data-astro-cid-j3ey47lz></path></svg></button></div><div class="fc-copy" data-astro-cid-a5zxh5oa><h3 class="fc-title" data-astro-cid-a5zxh5oa>Une licence signée</h3><p class="fc-text" data-astro-cid-a5zxh5oa>Quand le client saisit le code dans Kadenz, le portail émet la licence, signée par sa clé, et la renvoie au programme.</p></div></article></div><div class="hd-slide" data-astro-cid-j3ey47lz><article class="st-26 fc fc--picture" data-astro-cid-a5zxh5oa><div class="fc-media" data-astro-cid-a5zxh5oa><div class="hd-art hd-art--desk" aria-hidden="true" data-astro-cid-j3ey47lz><canvas data-motif="A2" data-cadre="vignette" data-piece="quart" data-decalage="0.9" aria-hidden="true" data-astro-cid-j3ey47lz></canvas></div><button type="button" class="hd-pause" data-hd-pause aria-pressed="false" aria-label="Pause" data-astro-cid-j3ey47lz><svg class="hd-pause-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M216,48V208a16,16,0,0,1-16,16H160a16,16,0,0,1-16-16V48a16,16,0,0,1,16-16h40A16,16,0,0,1,216,48ZM96,32H56A16,16,0,0,0,40,48V208a16,16,0,0,0,16,16H96a16,16,0,0,0,16-16V48A16,16,0,0,0,96,32Z" data-astro-cid-j3ey47lz></path></svg><svg class="hd-play-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M240,128a15.74,15.74,0,0,1-7.6,13.51L88.32,229.65a16,16,0,0,1-16.2.3A15.86,15.86,0,0,1,64,216.13V39.87a15.86,15.86,0,0,1,8.12-13.82,16,16,0,0,1,16.2.3L232.4,114.49A15.74,15.74,0,0,1,240,128Z" data-astro-cid-j3ey47lz></path></svg></button></div><div class="fc-copy" data-astro-cid-a5zxh5oa><h3 class="fc-title" data-astro-cid-a5zxh5oa>Une échéance calculée</h3><p class="fc-text" data-astro-cid-a5zxh5oa>Elle est calculée le jour de l'activation : l'échéance de la dernière licence si elle court encore, sinon la veille, plus un mois ou un an selon la formule. Dernier jour couvert, sans délai de grâce.</p></div></article></div><div class="hd-slide" data-astro-cid-j3ey47lz><article class="st-26 fc fc--picture" data-astro-cid-a5zxh5oa><div class="fc-media" data-astro-cid-a5zxh5oa><div class="hd-art hd-art--vars" aria-hidden="true" data-astro-cid-j3ey47lz><canvas data-motif="P" data-cadre="vignette" data-piece="quart" data-forme="arche" data-decalage="1.8" aria-hidden="true" data-astro-cid-j3ey47lz></canvas></div><button type="button" class="hd-pause" data-hd-pause aria-pressed="false" aria-label="Pause" data-astro-cid-j3ey47lz><svg class="hd-pause-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M216,48V208a16,16,0,0,1-16,16H160a16,16,0,0,1-16-16V48a16,16,0,0,1,16-16h40A16,16,0,0,1,216,48ZM96,32H56A16,16,0,0,0,40,48V208a16,16,0,0,0,16,16H96a16,16,0,0,0,16-16V48A16,16,0,0,0,96,32Z" data-astro-cid-j3ey47lz></path></svg><svg class="hd-play-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M240,128a15.74,15.74,0,0,1-7.6,13.51L88.32,229.65a16,16,0,0,1-16.2.3A15.86,15.86,0,0,1,64,216.13V39.87a15.86,15.86,0,0,1,8.12-13.82,16,16,0,0,1,16.2.3L232.4,114.49A15.74,15.74,0,0,1,240,128Z" data-astro-cid-j3ey47lz></path></svg></button></div><div class="fc-copy" data-astro-cid-a5zxh5oa><h3 class="fc-title" data-astro-cid-a5zxh5oa>Chacun ses entreprises</h3><p class="fc-text" data-astro-cid-a5zxh5oa>Un revendeur ne voit que les entreprises qui lui sont rattachées. Son nom est repris comme émetteur dans les licences qu'il émet.</p></div></article></div><div class="hd-slide" data-astro-cid-j3ey47lz><article class="st-26 fc fc--picture" data-astro-cid-a5zxh5oa><div class="fc-media" data-astro-cid-a5zxh5oa><div class="hd-art hd-art--files" aria-hidden="true" data-astro-cid-j3ey47lz><canvas data-motif="A2" data-cadre="vignette" data-piece="disque" data-decalage="2.7" aria-hidden="true" data-astro-cid-j3ey47lz></canvas></div><button type="button" class="hd-pause" data-hd-pause aria-pressed="false" aria-label="Pause" data-astro-cid-j3ey47lz><svg class="hd-pause-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M216,48V208a16,16,0,0,1-16,16H160a16,16,0,0,1-16-16V48a16,16,0,0,1,16-16h40A16,16,0,0,1,216,48ZM96,32H56A16,16,0,0,0,40,48V208a16,16,0,0,0,16,16H96a16,16,0,0,0,16-16V48A16,16,0,0,0,96,32Z" data-astro-cid-j3ey47lz></path></svg><svg class="hd-play-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M240,128a15.74,15.74,0,0,1-7.6,13.51L88.32,229.65a16,16,0,0,1-16.2.3A15.86,15.86,0,0,1,64,216.13V39.87a15.86,15.86,0,0,1,8.12-13.82,16,16,0,0,1,16.2.3L232.4,114.49A15.74,15.74,0,0,1,240,128Z" data-astro-cid-j3ey47lz></path></svg></button></div><div class="fc-copy" data-astro-cid-a5zxh5oa><h3 class="fc-title" data-astro-cid-a5zxh5oa>Un journal scellé</h3><p class="fc-text" data-astro-cid-a5zxh5oa>Le sceau est l'empreinte de la dernière entrée vérifiée. Noté hors du serveur, il permet de constater plus tard que rien n'a changé avant lui.</p></div></article></div><div class="hd-slide" data-astro-cid-j3ey47lz><article class="st-26 fc fc--picture" data-astro-cid-a5zxh5oa><div class="fc-media" data-astro-cid-a5zxh5oa><div class="hd-art hd-art--ease" aria-hidden="true" data-astro-cid-j3ey47lz><canvas data-motif="P" data-cadre="vignette" data-piece="quart" data-forme="ruine" data-decalage="3.6" aria-hidden="true" data-astro-cid-j3ey47lz></canvas></div><button type="button" class="hd-pause" data-hd-pause aria-pressed="false" aria-label="Pause" data-astro-cid-j3ey47lz><svg class="hd-pause-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M216,48V208a16,16,0,0,1-16,16H160a16,16,0,0,1-16-16V48a16,16,0,0,1,16-16h40A16,16,0,0,1,216,48ZM96,32H56A16,16,0,0,0,40,48V208a16,16,0,0,0,16,16H96a16,16,0,0,0,16-16V48A16,16,0,0,0,96,32Z" data-astro-cid-j3ey47lz></path></svg><svg class="hd-play-icon" viewBox="0 0 256 256" aria-hidden="true" data-astro-cid-j3ey47lz><path fill="currentColor" d="M240,128a15.74,15.74,0,0,1-7.6,13.51L88.32,229.65a16,16,0,0,1-16.2.3A15.86,15.86,0,0,1,64,216.13V39.87a15.86,15.86,0,0,1,8.12-13.82,16,16,0,0,1,16.2.3L232.4,114.49A15.74,15.74,0,0,1,240,128Z" data-astro-cid-j3ey47lz></path></svg></button></div><div class="fc-copy" data-astro-cid-a5zxh5oa><h3 class="fc-title" data-astro-cid-a5zxh5oa>Un compte qu'on coupe</h3><p class="fc-text" data-astro-cid-a5zxh5oa>Un compte désactivé ne peut plus se connecter et ses sessions sont fermées.</p></div></article></div></div></div></div></div></section>"##;

